.stop a:focus-visible { outline-offset: 4px; }
.stop .pic { position: relative; aspect-ratio: 3 / 2; overflow: hidden; }
.stop .pic::after { content: ""; position: absolute; inset: 0; background: linear-gradient(to top, var(--card) 0%, transparent 45%); }
.stop img { width: 100%; height: 100%; object-fit: cover; display: block; transition: transform .7s cubic-bezier(.2, .6, .2, 1); }
.stop .text { position: relative; flex: 1; display: flex; flex-direction: column; align-items: flex-start; gap: 10px; padding: 0 24px 24px; margin-top: -28px; }
.stop small { font-size: 12px; color: var(--band-fg); border: 1px solid var(--band-edge); border-radius: 4px; padding: 2px 8px; }
.stop b { font-family: var(--display); font-weight: 400; font-size: 32px; line-height: 1.15; letter-spacing: 0; }
.stop .text > span { font-size: 15px; color: var(--band-muted); }
.stop .pill { margin-top: auto; color: #fff; text-align: left; }
.stop .text > span + .pill { margin-top: max(8px, auto); }
.stop .pill i { font-style: normal; margin-left: 8px; transition: transform .3s; }
@media (hover: hover) {
  .stop a:hover img { transform: scale(1.04); }
  .stop a:hover .pill i { transform: translateX(4px); }
}
@media (prefers-reduced-motion: reduce) { .stop img, .stop .pill i { transition: none; } }

