// Survey string leaves in every car.js: key → count, chars, sample.
import tour from "/Users/kunabel/workspace/MercedesExperience/stops/tour.js";
const stats = new Map(); let total = 0, words = 0;
function walk(v, path) {
  if (typeof v === "string") {
    const key = path.filter(p => typeof p === "string").slice(-1)[0] ?? "?";
    const k = path.map(p => typeof p === "number" ? "[]" : p).join(".");
    const s = stats.get(k) ?? { n: 0, chars: 0, sample: v }; s.n++; s.chars += v.length; stats.set(k, s); total += v.length; words += v.split(/\s+/).length;
  } else if (Array.isArray(v)) v.forEach((x, i) => walk(x, [...path, i]));
  else if (v && typeof v === "object") for (const [k, x] of Object.entries(v)) walk(x, [...path, k]);
}
