1
=== victoria
{ "title": "How the Victoria steers", "name": "Benz Victoria", "summary": "Carl Benz's double-pivot steering: each front wheel on its own pivot, angled so both follow one turning circle.", "eyebrow": "Benz Victoria, 1893", "lede": "The first Benz with double-pivot steering, seen from above. Steer it, then switch to the carriage-style centre-pivot axle it replaced and compare where the wheel axes meet.", "photo": { "alt": "1893 Benz Vis-à-Vis, a Victoria with a facing front seat, on display in the Mercedes-Benz Museum, seen from the front right" }, "components": [ { "label": "Steering", "params": { "label": "Front steering, seen from above" }, "talk": [ "Horse carriages steered with a centre-pivot axle: the whole front axle swings on a turntable. Try it: at full lock the inner wheel swings back towards the body and the car stands on a narrower base.", "Benz's answer, patented in 1893 (DRP 73515) and first fitted to the Victoria: the axle stays put and each front wheel turns on its own pivot at the end of the axle.", "The steering arms point in towards the rear axle, so the inner wheel turns further than the outer one. Their axes then almost meet in one point on the rear-axle line, and the wheels roll round the corner instead of scrubbing. Watch the two coloured lines.", "Carriage builders Lankensperger and Ackermann had described the idea around 1817; Benz made it work on a motor car. In 1894 Theodor von Liebieg drove his Victoria about 939 km from Reichenberg in Bohemia to Reims." ] } ], "note": "Geometry is illustrative: wheelbase, track, wheel sizes and steering-arm geometry are plausible values, not measurements of the car.", "unverified": [ "Wheelbase, track, wheel sizes and steering-arm geometry", "Ghost-body outline (traced from the photo)", "Which car is shown: the photo is the museum's 1893 Vis-à-Vis, the Victoria with a facing front seat", "Room and level" ] }
=== velo
{ "title": "Two belts and a loose pulley", "name": "Benz Velo", "summary": "The first car built in series: 1.5 hp, two flat belts for two gears, and a loose pulley as the clutch.", "eyebrow": "Benz Velo, 1894", "lede": "Karl Benz's small, affordable car sold about 1,200 by 1902. Change gear by moving a belt from its loose pulley to its fixed one, then find out how steep a hill 1.5 hp can take with two people aboard.", "photo": { "alt": "Black 1894 Benz Velo with large wire rear wheels and a copper-panelled body in the Mercedes-Benz Museum, seen from the rear right" }, "components": [ { "label": "Belts and chains", "params": { "label": "Two belts, loose pulleys, chains", "drive": { "gears": [ { "name": "Low" }, { "name": "High" } ] } }, "talk": [ "Two flat belts run from the engine to a countershaft under the seat, one for each gear. Beside each fixed pulley on the countershaft turns a loose one; a belt on its loose pulley drives nothing. Sliding a belt across is both the gear change and the clutch.", "The countershaft holds the differential. From each end a chain runs back to a sprocket on a rear wheel.", "1.5 hp at 450 rpm gives about 20 km/h in high gear on the level. With two people aboard a slope of a few per cent stops it in high; low gear manages about 4 %. On steeper hills the passengers got out and pushed.", "So that a car stopped on a hill would not roll back, the Velo had a hill holder, a prop dropped onto the road, beside its wooden brake blocks on the solid rubber tyres." ] }, { "label": "Engine", "params": { "label": "Single cylinder, lying flat at the back" }, "talk": [ "One horizontal cylinder of 1,045 cm³ (110 × 110 mm) gives 1.5 hp at 450 rpm.", "Unlike the Patent-Motorwagen's, the flywheel stands upright, turning across the car.", "Benz kept electric ignition, with a coil and a spark plug; the intake valve is sucked open by the piston and only the exhaust valve is driven.", "The engine sits at the back under the rear seat; fuel came first from a surface carburettor, later from a float carburettor." ] } ], "note": "Benz built 67 Velos in 1894 and 134 in 1895, and about 1,200 Velo and Comfortable cars by 1902, at 2,000 marks. A Velo took part in the Paris–Rouen run of 1894. A third gear and reverse were optional from 1896 and standard from 1900.", "unverified": [ "Pulley and sprocket sizes, and the low-gear speed (about 12 km/h)", "Laden mass (two people aboard), rolling resistance and driveline efficiency", "Engine, flywheel and countershaft positions, conrod length", "Ghost-body outline (traced from the photo)", "Room: Legend 1" ] }
