// Hungarian text for car.js, merged over it by loadCar (lib/app/i18n.js): same shape, strings only, null keeps the original.
export default {
  title: "Hogyan kormányoz a Victoria",
  name: "Benz Victoria",
  summary: "Carl Benz kétcsapos kormányzása: mindkét első kerék saját csapja körül fordul, olyan szögben, hogy mindkettő ugyanazt a fordulókört kövesse.",
  eyebrow: "Benz Victoria, 1893",
  lede: "Az első kétcsapos kormányzású Benz, felülről nézve. Kormányozza, aztán váltson a lovaskocsik középen forgó tengelyére, amelyet felváltott, és hasonlítsa össze, hol metszik egymást a kerekek tengelyvonalai.",
  photo: { alt: "Az 1893-as Benz Vis-à-Vis, egy szemben ülős első üléssel épült Victoria, a Mercedes-Benz Múzeumban, jobbról elölről nézve" },
  components: [
    {
      label: "Kormányzás",
      params: { label: "Első kormányzás, felülről" },
      talk: [
        "A lovaskocsikat középen forgó tengellyel kormányozták: az egész első tengely egy forgózsámolyon fordul el. Próbálja ki: teljes kormánykitérésnél a belső kerék a kocsiszekrény felé lendül, és a jármű keskenyebb alapon áll.",
        "Benz válasza, amelyet 1893-ban szabadalmaztatott (DRP 73515), és először a Victoriába épített be: a tengely a helyén marad, és mindkét első kerék a tengely végén lévő saját csapja körül fordul.",
        "A kormánykarok befelé, a hátsó tengely felé mutatnak, így a belső kerék jobban elfordul, mint a külső. A tengelyvonalaik ezért majdnem egy pontban találkoznak a hátsó tengely vonalán, és a kerekek csúszás nélkül gördülnek végig a kanyaron. Figyelje a két színes vonalat.",
        "Lankensperger és Ackermann kocsigyártók már 1817 körül leírták az elvet; Benz motoros kocsin valósította meg. 1894-ben Theodor von Liebieg Victoriájával mintegy 939 km-t tett meg a csehországi Reichenbergből Reimsig.",
      ],
    },
  ],
  note: "A geometria szemléltető: a tengelytáv, a nyomtáv, a kerékméretek és a kormánykarok geometriája valószerű értékek, nem az autón mért adatok.",
  unverified: [
    "Tengelytáv, nyomtáv, kerékméretek és a kormánykarok geometriája",
    "A jármű körvonala (a fotóról átrajzolva)",
    "Melyik autó látható: a fotón a múzeum 1893-as Vis-à-Vis-je, a szemben ülős első üléssel épült Victoria",
    "Terem és szint",
  ],
};

