// Hungarian text for car.js, merged over it by loadCar (lib/app/i18n.js): same shape, strings only, null keeps the original.
export default {
  title: "Négy rotor, dugattyúk nélkül",
  name: "Mercedes-Benz C 111-II",
  summary: "Narancssárga, középmotoros kísérleti autó négyrotoros Wankel-motorral: 350 LE és 300 km/h.",
  eyebrow: "Mercedes-Benz C 111-II, 1970",
  lede: "Se dugattyú, se szelep: négy háromszögletű rotor forog ovális házakban. Figyelje, ahogy egy rotor három kamrája végigmegy a szíváson, a sűrítésen, a munkaütemen és a kipufogáson, egyszerre, egymáshoz képest harmad fordulattal eltolva.",
  photo: { alt: "Narancssárga, 1970-es Mercedes-Benz C 111 megemelt talapzaton a Mercedes-Benz Múzeumban, balról hátulról nézve" },
  components: [
    {
      label: "Forgódugattyús motor",
      params: { label: "Négyrotoros Wankel-motor" },
      talk: [
        "Felix Wankel motorjában kamracsoportonként egyetlen mozgó alkatrész van: egy excenteren forgó, ívelt oldalú háromszög. Csúcsai egy kövér nyolcasra emlékeztető házhoz tömítenek.",
        "A rotor a tengely minden három fordulatára egyszer fordul körbe. Mindhárom oldala rotorfordulatonként egy munkaütemet ad, így minden rotor tengelyfordulatonként egyszer gyújt.",
        "A C 111-II M 950 F motorjában négy rotor van, kamránként 600 cm³-rel, 9,3 : 1 sűrítéssel és kb. 350 LE-vel. Az autót 1970 márciusában Genfben mutatták be, és 300 km/h-t ért el.",
        "A Mercedes sosem gyártotta sorozatban: a Wankel sokat fogyasztott, és csúcstömítései kopottak. 1970 végétől a C 111 inkább dízel- és V8-as motorokkal járt.",
      ],
    },
  ],
  note: "A források eltérnek abban, hogy a motort 2,4 vagy 4,8 literesnek kell-e tekinteni, és egyesek 350 LE-t adnak meg 7000/min fordulaton. A modell sűrítési aránya az itt rajzolt rotoralakból adódik.",
  unverified: [
    "A rotoroldal alakja (9,3 : 1-hez választva)",
    "A rotorok fáziseltolása és távolsága",
    "A motor helyzete és a jármű körvonala",
    "7000/min névleges fordulat",
  ],
};

// Hungarian text for car.js, merged over it by loadCar (lib/app/i18n.js): same shape, strings only, null keeps the original.
export default {
  title: "A másik SL",
  name: "Mercedes-Benz 190 SL",
  summary: "A 300 SL megfizethető testvére: ugyanaz a külső, limuzinpadlólemez és egy új, 1,9 literes, felül vezérműtengelyes négyhengeres.",
  eyebrow: "Mercedes-Benz 190 SL, 1959",
  lede: "Úgy néz ki, mint egy 300 SL, de alatta sokkal egyszerűbb. Motorja négyhengeres a 300 SL furatával és a hengerfejben ülő, lánccal hajtott vezérműtengellyel. Figyelje, ahogy a bütyök közvetlenül nyitja a szelepeket, miközben a négy henger sorban gyújt.",
  photo: { alt: "Szürke, piros ülésű, 1958-as Mercedes-Benz 190 SL roadster leengedett tetővel a Mercedes-Benz Múzeumban, balról elölről nézve" },
  components: [
    {
      label: "Motor",
      params: { label: "M 121 négyhengeres, felül fekvő vezérműtengely · gyújtási sorrend 1-3-4-2" },
      talk: [
        "A 190 SL formája és felfüggesztési elrendezése a 300 SL-é: elöl keresztlengőkarok, hátul lengőtengely. Csővázas térháló helyett azonban a limuzinok megrövidített padlólemezén ül, így sokkal olcsóbb volt építeni.",
        "Motorja, az M 121, új volt: négy henger a 300 SL 85 mm-es furatával és 83,6 mm-es lökettel, összesen 1,9 liter, amely két kéttorkú Solex porlasztóval 5700/min fordulaton 105 LE-t adott.",
        "A hengerfejben egyetlen, kettős görgős lánccal hajtott vezérműtengely nyitja mind a nyolc szelepet. Közbülső szelepemelő rudak nélkül a szelepvezérlés könnyű marad, és nagy fordulaton is követi a bütyköt.",
        "Gyújtási sorrend 1-3-4-2: minden fél fordulatra egy munkaütem. Az 1. és a 4. dugattyú együtt emelkedik és süllyed, a 2. és a 3. velük ellentétesen. Visszafogottabb hangolással ugyanez a motor hajtotta később a 180-as és a 190-es limuzint.",
      ],
    },
  ],
  note: "2017 óta a múzeum 190 SL-je egy felújítatlan, 1959-es roadster, amely David Scott űrhajósé volt, a Holdra lépő hetedik emberé: újonnan vette, és 2004-ig megtartotta. A 2013-as fotó az előtte kiállított autót mutatja.",
  unverified: [
    "A motor helyzete az autóban és a hajtórúdhossz",
    "A fotóillesztéshez használt lámpa- és csillaghelyzetek",
    "A jármű körvonala (az adatlap méreteiből és a fotóról átrajzolva)",
    "Terem: Gyűjtemény 4 (a kutatási jegyzetek szerint Legenda 4)",
  ],
};

