// Hungarian text for car.js, merged over it by loadCar (lib/app/i18n.js): same shape, strings only, null keeps the original.
export default {
  title: "Burkolt vagy szabad kerekek",
  name: "Mercedes-Benz W 196 R áramvonalas",
  summary: "A Forma–1-es autó, amely két karosszériával készült: burkolt kerekekkel a gyors pályákra, szabad kerekekkel a kanyargósakra.",
  eyebrow: "Mercedes-Benz W 196 R áramvonalas versenyautó, 1955",
  lede: "A Mercedes két karosszériát tervezett 1954-es Grand Prix-autójához. A kerekek burkolása csökkenti a légellenállást a hosszú egyeneseken; a szabad kerekekkel könnyebb az autó, és a vezető pontosabban helyezheti el a kanyarokban. Váltson karosszériát, és nézze meg, mit ér a burkolat teljes teljesítményen.",
  photo: { alt: "Ezüst, burkolt kerekű, 18-as rajtszámú, 1955-ös Mercedes-Benz W 196 R áramvonalas versenyautó a Mercedes-Benz Múzeumban, balról elölről nézve" },
  components: [
    {
      label: "Légellenállás",
      params: { label: "Teljes teljesítmény a monzai egyenesen", shapes: [{ label: "Áramvonalas karosszéria" }, { label: "Szabad kerekek" }] },
      talk: [
        "Az 1954-es új, 2,5 literes Forma–1-re a Mercedes kezdettől két karosszériát tervezett: ezt az áramvonalasat a nagyon gyors pályákra, és egy klasszikusat szabad kerekekkel.",
        "A szabadon forgó kerék felkavarja a levegőt, és nagy örvénylő nyomot hagy. A burkolat szélesebbé teszi a karosszériát, így több levegőt tol félre, a teljes légellenállás mégis csökken. Váltson karosszériát: ugyanazzal a 290 LE-vel ebben a modellben az áramvonalas kb. 20 km/h-val gyorsabb.",
        "Első versenyén győzött, Reimsben, 1954. július 4-én: Fangio Kling előtt. Két héttel később a szűk silverstone-i pályán a versenyzők nem tudták pontosan elhelyezni a burkolt első kerekeket a kanyarokban, és csak 4. és 7. helyen végeztek.",
        "1955-ben az áramvonalas csak egyszer versenyzett, Monzában, az új, meredek döntött kanyarokkal, ahol Fangio nyert. Az M 196 motor, egy közvetlen befecskendezéses, deszmodromikus szelepvezérlésű soros nyolchengeres, ekkor már 8500/min fordulaton 290 LE-t adott.",
      ],
    },
  ],
  note: "Az áramvonalas a szokásos 2350 mm-es tengelytávval futott; egy 2210 mm-es változatot 1955-ben Monzában kipróbáltak, de nem versenyeztették. Fangio mindkét idényben világbajnok lett.",
  unverified: [
    "Légellenállási tényezők, homlokfelületek, tömegek és a hajtáslánc hatásfoka (végsebesség-adat nincs, így nincs mivel összevetni)",
    "A fotóillesztéshez használt nyomtávok, kerékméret és az orr helyzete (közelítő: a kerekek pontjai majdnem egy egyenesbe esnek)",
    "A jármű körvonala (a fotóról átrajzolva)",
    "Terem: Legenda 7",
  ],
};

