// The museum route, in walking order (the museum is visited from level 8 downwards; Legend n is on level 9 − n).
// Single source for stop order and prev/next. Each slug has stops/<slug>/car.js. Rooms/levels: confirm on site.
export default [
  { slug: "daimler-engine", room: "Legend 1", level: 8 },
  { slug: "reitwagen", room: "Legend 1", level: 8 },
  { slug: "patent-motorwagen", room: "Legend 1", level: 8 },
  { slug: "daimler-boat", room: "Legend 1", level: 8 },
  { slug: "victoria", room: "Legend 1", level: 8 },
  { slug: "velo", room: "Legend 1", level: 8 },
  { slug: "daimler-van", room: "Legend 1", level: 8 },
  { slug: "simplex", room: "Legend 2", level: 7 },
  { slug: "blitzen-benz", room: "Legend 2", level: 7 },
27
  { slug: "papamobil", room: "Collection 4", level: 4 },
  { slug: "190e", room: "Legend 6", level: 3 },
  { slug: "w196r", room: "Legend 7", level: 2 },
  { slug: "500slc", room: "Legend 7", level: 2 },
];
----
// Build the deployable site into _site/: copy the site files, then stamp the service worker with a content-hash VERSION
// and the full precache list, so one visit stores every stop. Node built-ins only. Usage: node tools/build.mjs
import { cp, rm, mkdir, readdir, readFile, writeFile } from "node:fs/promises";
import { createHash } from "node:crypto";
import { join } from "node:path";
import { fileURLToPath } from "node:url";

const root = fileURLToPath(new URL("..", import.meta.url)), out = join(root, "_site");
const ENTRIES = ["index.html", "stop.html", "sw.js", "manifest.webmanifest", "icons", "lib", "stops", "subsystems", "vendor"];
const SKIP = /(^|\/)\.|\.svg$/;   // dotfiles (.DS_Store) and the icon source

await rm(out, { recursive: true, force: true });
await mkdir(out);
for (const e of ENTRIES) await cp(join(root, e), join(out, e), { recursive: true, filter: src => !SKIP.test(src.slice(root.length)) });

async function walk(dir, base = "") {
  const files = [];
  for (const d of await readdir(join(dir, base), { withFileTypes: true })) {
    const rel = base ? `${base}/${d.name}` : d.name;
    if (d.isDirectory()) files.push(...await walk(dir, rel)); else files.push(rel);
  }
  return files;
}

const files = (await walk(out)).filter(f => f !== "sw.js").sort();
