// Teaser screenshots: hero and cards at desktop (en) and phone (hu), plus a teaser stop's header and pager on the phone.
import { webkit, devices } from "/Users/kunabel/workspace/MercedesExperience/node_modules/@playwright/test/index.mjs";
const out = process.argv[2], base = "http://localhost:8765/";
const browser = await webkit.launch();
for (const [name, dev, locale] of [["desktop", { viewport: { width: 1440, height: 900 } }, "en-US"], ["phone", devices["iPhone 15"], "hu-HU"]]) {
  const ctx = await browser.newContext({ ...dev, locale, colorScheme: "light" }), page = await ctx.newPage(), errors = [];
  page.on("pageerror", e => errors.push(e.message));
  await page.goto(base + "teaser.html");
  await page.waitForSelector(".stop img");
  await page.evaluate(async () => { for (const i of document.images) { i.loading = "eager"; await i.decode().catch(() => {}); } });
  await page.screenshot({ path: `${out}/teaser-${name}.png`, fullPage: true });
  await page.goto(base + "stop.html?s=300sl&r=teaser&debug");
  await page.waitForFunction(() => window.__tour?.stats.frames > 10, null, { timeout: 20000 });
  await page.screenshot({ path: `${out}/teaser-stop-${name}.png` });
  console.log(name, "where:", await page.locator("#where").innerText(), "| back:", await page.locator("#back").innerText(),
    "| pager:", await page.locator(".pager").innerText(), "| errors", errors, "| missing", await page.evaluate(() => window.__tour.missing()));
  await ctx.close();
}
await browser.close();

